3. What is the output?
package com.a;
public class Parent {
    protected int value = 10;
}

package com.b;
import com.a.Parent;
public class Child extends Parent {
    public void show() {
        System.out.println(value);       // Line A
        Parent p = new Parent();
        System.out.println(p.value);    // Line B
    }
}

4. Fix the encapsulation violation:
public class Team {
    public List<String> members = new ArrayList<>();
    public String teamName;
}

5. Is the following override valid? Why or why not?
class Vehicle {
    public void start() { System.out.println("Starting"); }
    protected void stop() { System.out.println("Stopping"); }
}
class Truck extends Vehicle {
    @Override
    protected void start() { System.out.println("Truck starting"); }
    @Override
    public void stop() { System.out.println("Truck stopping"); }
}

6. What is the output and why?
class Animal {
    private void sound() { System.out.println("Animal sound"); }
    public void makeSound() { sound(); }
}
class Dog extends Animal {
    public void sound() { System.out.println("Woof"); }
}
public class Main {
    public static void main(String[] args) {
        Animal a = new Dog();
        a.makeSound();
    }
}

